/// Root overrides shared by fresh bootstrap and every supported Flutter SDK.
String rootDependencyOverrides() {
  const uikitPackages = [
    'tencent_cloud_chat_common',
    'tencent_cloud_chat_message',
    'tencent_cloud_chat_conversation',
    'tencent_cloud_chat_contact',
    'tencent_cloud_chat_sticker',
    'tencent_cloud_chat_intl',
    'tencent_cloud_chat_text_translate',
    'tencent_cloud_chat_sound_to_text',
  ];
  final overrides = StringBuffer(
    '# Generated by tool/bootstrap_deps.dart - do not edit.\n',
  );
  overrides.writeln('dependency_overrides:');
  overrides.writeln('  tim2tox_dart:');
  overrides.writeln('    path: third_party/tim2tox/dart');
  overrides.writeln('  tencent_cloud_chat_sdk:');
  overrides.writeln('    path: third_party/tencent_cloud_chat_sdk');
  for (final p in uikitPackages) {
    overrides.writeln('  $p:');
    overrides.writeln('    path: third_party/chat-uikit-flutter/$p');
  }
  // Vendored (MIT): published 0.9.36 leaks every screenshot's ui.Image —
  // debug app dies ~770MB RSS. Drop when upstream ships the dispose fix.
  overrides.writeln('  flutter_skill:');
  overrides.writeln('    path: third_party/flutter_skill');
  // Vendored: record_android 1.2.1 can double-reply stop() from the encoder
  // thread ("Reply already submitted" -> app FATAL, live during call
  // teardown). Idempotent-reply guard in RecorderWrapper.stop.
  overrides.writeln('  record_android:');
  overrides.writeln('    path: third_party/record_android');
  overrides.writeln('  record_linux: ^1.2.1');
  // Official 17.0.0 removes a Flutter 3.44-deleted intent while retaining the
  // existing adjacent-page selection action. Keep resolution identical across
  // the 3.41.9 baseline and the native Windows ARM64 3.44.0 toolchain.
  overrides.writeln('  extended_text_field: 17.0.0');
  // integration_test pins file 7.0.1 while the fork intl asks for ^6.1.2;
  // the used APIs are compatible, so all entry points share this override.
  overrides.writeln('  file: ^7.0.1');
  return overrides.toString();
}
